def absorb(args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    res = []
    for a in args:
        if isinstance(a, And):
            if a.left in res:
                res.remove(a.left)
                res.append(a.left | a.right)
            elif a.right in res:
                res.remove(a.right)
                res.append(a.left & a.right)
            else:
                res.append(a)
        elif isinstance(a, Or):
            if a.left == a.right:
                res.append(a.left)
            else:
                res.append(a)
        else:
            res.append(a)

    return res

