def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    import subprocess
    import shlex
    import os
    import sys

    # Validate input
    if not isinstance(commands, list):
        raise ValueError("Invalid argument 'commands'. Expected a list of command strings")
    if not isinstance(args, list):
        raise ValueError("Invalid argument 'args'. Expected a list of command arguments")
    if not isinstance(cwd, str) and cwd is not None:
        raise ValueError("Invalid argument 'cwd'. Expected a string or None")
    if not isinstance(verbose, bool):
        raise ValueError("Invalid argument 'verbose'. Expected a bool")
    if not isinstance(hide_stderr, bool):
        raise ValueError("Invalid argument 'hide_stderr'. Expected a bool")
    if not isinstance(env, dict) and env is not None:
        raise ValueError("Invalid argument 'env'. Expected a dict or None")

    # Build command string
    command_strings = [shlex.split(command) for command in commands]
    if cwd is not None:
        os.chdir(cwd)
    if env is not None:
        os.environ.update(env)

    # Run command(s)
    proc = subprocess.Popen(command_strings, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = proc.communicate(input=args)

    # Display output
    if verbose:
        sys.stdout.write(stdout.decode(errors='ignore'))
    if hide_stderr:
        sys.stderr.seek(0)
        sys.stderr.truncate(0)

    return stdout, stderr

