    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return "0.1"

    if version == "0.1":
        return "1.0"

    splitted = version.split(".")
    major = parse_int(splitted[0])
    minor = parse_int(splitted[1])

