def deep_merge_nodes(nodes):
      nodes = sorted(nodes, key=lambda x: x[0], reverse=True)
      merged = []
      for node in nodes:
          key = node[0]
          value = node[1]
          if len(merged) == 0 or merged[-1][0] != key:
              merged.append(node)
          else:
              value = merged[-1][1]
              if not isinstance(value, ruamel.yaml.nodes.MappingNode):
                  merged.pop()
                  merged.append(node)
              else:
                  for pair in value:
                      if len(pair) == 2 and pair[0][0] == key:
                          merged[-1][1] = pair[1]
                          break
                  else:
                      merged[-1][1][pair] = value
      return merged

