def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """

    if other is None:
        return self._scale

    if not isinstance(other, numbers.Real):
        raise LenaValueError("The scale must be a number.")

    if self._scale == 0 or self._scale is None:
        raise LenaValueError("Cannot rescale a graph with unknown scale.")

    for field in self.fields:
        if field != "ID" and field != "GS":
            values = self[field]
            if not isinstance(values, list):
                values = [values]
            for value in values:
                if value != 0 and value is not None:
                    value *= other / self._scale

    self._scale = other

def verifyObject(iface, candidate, tentative=False):
    # Making sure the candidate claims that it provides the interface
    if not tentative:
        assert isinstance(iface, Interface)
        assert iface.providedBy(candidate)
        assert iface.implementedBy(candidate.__class__)

    # Making sure the candidate defines all the necessary methods
    for name, func in iface.getMethods():
        try:
            candidate__getattr__(name)
        except AttributeError:
            raise Invalid("Method '{0}' is not provided by {1}.".format(name, candidate))

    # Making sure the methods have the correct signature
    for name, func in iface.getMethods():
        try:
            candidate_func = candidate.__getattr__(name)
            assert len(func.signature) == len(candidate_func.signature)
            for i, param in enumerate(func.signature):
                assert param[0] == candidate_func.signature[i][0]
                assert param[1] == candidate_func.signature[i][1]
        except Invalid:
            raise Invalid("Method '{0}' has an incorrect signature for {1}.".format(name, candidate))

    # Making sure the candidate defines all the necessary attributes
    for name, typ in iface.getAttributes():
        try:
            candidate_attr = candidate.__getattr__(name)
            assert typ(candidate_attr)
        except AttributeError:
            raise Invalid("Attribute '{0}' is not provided by {1}.".format(name, candidate))

    return True

