def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    parsed_data = {}
    if document[0:5] == '<?xml':
        xrd = ET.parse(StringIO(document))
        for element in xrd.iter():
            if element.tag == 'Type':
                # No need to handle 'application/activity+json'
                if element.text == 'application/activity+json':
                    continue
                if element.text not in parsed_data:
                    parsed_data[element.text] = []
                parsed_data[element.text].append(element.text)
            elif element.tag == 'Link':
                # href is the key, rel is the value
                parsed_data[element.attrib['rel']] = element.attrib['href']


    else:
        # JSON payload
        parsed_data = json.loads(document)
        if 'rels' in parsed_data:
            for key, value in parsed_data['rels'].items():
                if key not in parsed_data:
                    parsed_data[key] = []
                parsed_data[key].append(value)
    return parsed_data

